import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int[] up = new int[n], down = new int[n];
        Arrays.fill(up, 1);
        Arrays.fill(down, 1);
        for (int i = 1; i < n; i++) if (a[i] >= a[i - 1]) up[i] = up[i - 1] + 1;
        for (int i = n - 2; i >= 0; i--) if (a[i] >= a[i + 1]) down[i] = down[i + 1] + 1;
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, up[i] + down[i] - 1);
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	up, down := make([]int, n), make([]int, n)
	for i := range up {
		up[i], down[i] = 1, 1
	}
	for i := 1; i < n; i++ {
		if a[i] >= a[i-1] {
			up[i] = up[i-1] + 1
		}
	}
	for i := n - 2; i >= 0; i-- {
		if a[i] >= a[i+1] {
			down[i] = down[i+1] + 1
		}
	}
	best := 0
	for i := 0; i < n; i++ {
		best = max(best, up[i]+down[i]-1)
	}
	w.WriteString(strconv.Itoa(best) + "\n")
}
